alter table public.profiles add column pen_name text not null default '' check(length(pen_name)<=80),add column bio text not null default '' check(length(bio)<=280),add column avatar_path text not null default '',add column default_credit text not null default 'Display name' check(default_credit in ('Display name','Pen name','Anonymous Panelist')),add column profile_public boolean not null default false,add column history_public boolean not null default false,add column workbench_visible boolean not null default false,add column interests text[] not null default '{}',add column motion_preference text not null default 'Follow system' check(motion_preference in ('Follow system','Reduce motion')),add column workshop_density text not null default 'Comfortable' check(workshop_density in ('Comfortable','Compact')),add column newsletter_opt_in boolean not null default false,add column status_email_opt_in boolean not null default false;
create policy profile_owner_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role=public.open_panel_role() and account_status=(select account_status from public.profiles where id=auth.uid()));
